1	// Package chainledger graph structure rules shared by every graph reader.
2	//
3	// Both on-disk graph files (UnmarshalGraphFile) and the graph embedded in a
4	// snapshot (ParseSnapshot) describe the same thing: a set of dataset names and
5	// each dataset's direct upstreams. The rules below are the single authority for
6	// turning that description into the validated, normalized adjacency both
7	// readers build on, so the two file formats can never disagree about whether
8	// one graph is legal or about which lineage relations it expresses:
9	//
10	//   - an empty dataset name is rejected;
11	//   - a dataset declared more than once is rejected;
12	//   - an upstream that is not itself a declared dataset is rejected, with the
13	//     referrer and the referenced name both in the error;
14	//   - a direct self-dependency or any indirect dependency cycle is rejected,
15	//     with the datasets on the cycle named;
16	//   - names are case-sensitive and surrounding whitespace is kept verbatim;
17	//   - every name's RAW string literal must decode faithfully: bytes that are
18	//     not valid UTF-8, or a \u escape forming an unpaired surrogate (a lone
19	//     high or low surrogate, or a low surrogate before its high surrogate),
20	//     reject the whole document — the decoder's U+FFFD rewrite is never kept
21	//     and the offending node or edge is never skipped, even when the rewrite
22	//     would collide with a real dataset or match the snapshot's declared
23	//     content identifier; that raw scan is shared by every graph and plan
24	//     reader and lives in name_encoding.go (the graph document scope is in
25	//     graph_name_encoding.go);
26	//   - record order and upstream order are irrelevant, duplicate upstreams count
27	//     as one relationship, and an empty upstream list marks a root, so an
28	//     empty graph stays legal;
29	//   - a known field declared twice within the same object (datasets in the
30	//     graph object, name or upstreams in a dataset record) is rejected,
31	//     however the two declarations are spelled; that JSON-level scan is
32	//     shared by every document reader and lives in duplicate_fields.go.
33	//
34	// The snapshot-only envelope rules (required fields, format version, content
35	// identifier, and duplicates of the snapshot's own fields) live in
36	// snapshot.go; this file is only the common graph structure.
37	package chainledger
38	
39	import (
40		"fmt"
41		"sort"
42		"strings"
43		"unicode/utf8"
44	)
45	
46	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
47	type adjacency map[string][]string
48	
49	// validateInMemoryNamesUTF8 rejects an in-memory graph whose dataset name or
50	// direct upstream reference is not valid UTF-8.
51	//
52	// Such names cannot exist in a file read by the JSON readers (json.Unmarshal
53	// replaces invalid bytes with U+FFFD), but they can exist in a graph built
54	// through Register or by hand. They must never reach an exporter: encoding/json
55	// would silently replace every invalid byte with U+FFFD, so two different
56	// names ("p\xff" and "p\xfe") could serialize identically and a re-read graph
57	// would no longer be a faithful copy. The whole graph is rejected instead.
58	//
59	// Nodes are visited in name byte order and each node's parents in their stored
60	// order, so the first reported name is stable regardless of map iteration.
61	// The offending name is quoted with %q, which keeps the raw bytes readable
62	// ("p\xff" differs from "p\xfe", and a genuinely valid "p�" is shown as
63	// the replacement character itself). The graph is only read, never modified.
64	// Nil lineage nodes are skipped here; the caller rejects those separately.
65	func validateInMemoryNamesUTF8(graph map[string]*Lineage) error {
66		names := make([]string, 0, len(graph))
67		for name := range graph {
68			names = append(names, name)
69		}
70		sort.Strings(names)
71		for _, name := range names {
72			if !utf8.ValidString(name) {
73				return fmt.Errorf("%w: dataset name %q is not valid UTF-8, so the graph cannot be exported faithfully", ErrInvalidArgument, name)
74			}
75			entry := graph[name]
76			if entry == nil {
77				continue
78			}
79			for _, parent := range entry.Parents {
80				if !utf8.ValidString(parent) {
81					return fmt.Errorf("%w: dataset %q references upstream %q whose name is not valid UTF-8", ErrInvalidArgument, name, parent)
82				}
83			}
84		}
85		return nil
86	}
87	
88	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
89	// records. It rejects empty dataset names and datasets declared more than
90	// once; every surviving upstream list is sorted and deduplicated. It does not
91	// check that upstreams resolve to a declared dataset; use
92	// validateAdjacencyReferences for that.
93	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
94		adj := make(adjacency, len(datasets))
95		for _, ds := range datasets {
96			if ds.Name == "" {
97				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
98			}
99			if _, exists := adj[ds.Name]; exists {
100				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
101			}
102			adj[ds.Name] = uniqueSorted(ds.Upstreams)
103		}
104		return adj, nil
105	}
106	
107	// validateAdjacencyReferences rejects an edge whose upstream is not a declared
108	// dataset. Referrers are visited in sorted order with their parents sorted, so
109	// the first reported (referrer, upstream) pair is stable regardless of map
110	// iteration or record order.
111	func validateAdjacencyReferences(adj adjacency) error {
112		names := make([]string, 0, len(adj))
113		for name := range adj {
114			names = append(names, name)
115		}
116		sort.Strings(names)
117		for _, name := range names {
118			for _, parent := range adj[name] {
119				if _, ok := adj[parent]; !ok {
120					return fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
121				}
122			}
123		}
124		return nil
125	}
126	
127	// validateGraphStructureFromFile runs every graph-structure rule shared by the
128	// file readers: it normalizes the records, rejects empty names, duplicate
129	// datasets, and unregistered upstreams, then rejects cycles. The returned
130	// adjacency is the canonical form of the graph's semantics.
131	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
132		adj, err := normalizeDatasets(datasets)
133		if err != nil {
134			return nil, err
135		}
136		if err := validateAdjacencyReferences(adj); err != nil {
137			return nil, err
138		}
139		if err := validateAcyclic(adj); err != nil {
140			return nil, err
141		}
142		return adj, nil
143	}
144	
145	// validateAcyclic reports an error if the parent adjacency contains a cycle
146	// (including a dataset that depends on itself). The error message names the
147	// datasets involved.
148	func validateAcyclic(adj adjacency) error {
149		const (
150			white = 0
151			gray  = 1
152			black = 2
153		)
154		color := make(map[string]int, len(adj))
155		var stack []string
156	
157		var dfs func(node string) error
158		dfs = func(node string) error {
159			color[node] = gray
160			stack = append(stack, node)
161			for _, parent := range adj[node] {
162				switch color[parent] {
163				case gray:
164					// parent is an ancestor of node in the current DFS path, so
165					// following parent edges from parent leads back to parent.
166					idx := 0
167					for stack[idx] != parent {
168						idx++
169					}
170					cycle := make([]string, 0, len(stack)-idx+1)
171					cycle = append(cycle, stack[idx:]...)
172					cycle = append(cycle, parent)
173					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
174				case white:
175					if err := dfs(parent); err != nil {
176						return err
177					}
178				}
179			}
180			color[node] = black
181			stack = stack[:len(stack)-1]
182			return nil
183		}
184	
185		// Iterate over a sorted snapshot so the first reported cycle is stable
186		// across runs regardless of map iteration order.
187		names := make([]string, 0, len(adj))
188		for name := range adj {
189			names = append(names, name)
190		}
191		sort.Strings(names)
192		for _, name := range names {
193			if color[name] == white {
194				if err := dfs(name); err != nil {
195					return err
196				}
197			}
198		}
199		return nil
200	}
201	
202	// materializeLineage turns validated, normalized parent adjacency into the
203	// in-memory lineage structure every graph reader and every successful batch
204	// leave behind, so both operations follow exactly one relationship rule:
205	//
206	//   - one node exists per adjacency key, carrying an independent copy of its
207	//     sorted, duplicate-free parent list;
208	//   - children are derived in a second pass from the parent edges, so every
209	//     dataset's direct upstreams correspond to those upstreams' direct
210	//     downstreams, with each downstream registered once.
211	//
212	// into is optional: when nil a fresh graph map is allocated and returned
213	// (graph reads); when an existing graph is given (batch applies), nodes absent
214	// from adjacency are deleted and the surviving *Lineage records are reused in
215	// place, so Go callers that already hold the map or a node pointer keep reading
216	// the updated relationships through their own records. Replacing a node's
217	// lists with fresh copies keeps the result independent of adjacency: editing
218	// the plan's final graph or a previously returned report cannot move the
219	// materialized graph.
220	func materializeLineage(into map[string]*Lineage, adj adjacency) map[string]*Lineage {
221		if into == nil {
222			into = make(map[string]*Lineage, len(adj))
223		}
224		// Nodes absent from the adjacency no longer exist; delete them before any
225		// edge is rebuilt, so a removed dataset cannot leave its relationships in
226		// a retained node's lists.
227		for name := range into {
228			if _, ok := adj[name]; !ok {
229				delete(into, name)
230			}
231		}
232		// Install the parent lists first, clearing children. A full rebuild below
233		// derives every child from the parent edges; that wholesale derivation is
234		// what guarantees replaced edges vanish from the old upstream, new
235		// upstreams list the downstream once, and untouched relations survive.
236		for name, parents := range adj {
237			entry := into[name]
238			if entry == nil {
239				entry = &Lineage{}
240				into[name] = entry
241			}
242			entry.Dataset = name
243			entry.Parents = append([]string(nil), parents...)
244			entry.Children = nil
245		}
246		for name, parents := range adj {
247			for _, parent := range parents {
248				into[parent].Children = append(into[parent].Children, name)
249			}
250		}
251		for name := range into {
252			into[name].Children = uniqueSorted(into[name].Children)
253		}
254		return into
255	}
256	
257	// lineageFromAdjacency rebuilds a fresh in-memory graph from validated,
258	// normalized parent adjacency. It is the read path of the shared relationship
259	// rule in materializeLineage; the result is independent of the caller's record
260	// slices.
261	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
262		return materializeLineage(nil, adj)
263	}
